/**
 * @file PongPalette.h
 * @brief The 16-slot RGB565 arcade palette and the nibble tables that bind it.
 *
 * Every slot is assigned, in the order the court paints: slot 0 is the court
 * ink, then the inks the actors and the score band draw with, then the HUD's
 * spare shades. The renderer resolves primitives and sprites through this one
 * table, so a hole would not be a harmless gap - it would turn a named Color
 * into whatever the tail of the table held.
 *
 * Slot 0 is the trap this file exists to disarm. `Color::Black` is index 0 and
 * the engine's own palette gives it RGB565 0x0000 - the value the ESP32 8bpp
 * framebuffer reads as transparent. A 0x0000 in slot 0 makes every
 * `Color::Black` primitive silently disappear, so the court ink is a dark blue
 * that packs to a non-zero word instead. The static_assert below is the
 * tripwire for that regression.
 *
 * The engine stores the pointer it is handed and never copies it, so this
 * array has static storage duration: it outlives every frame drawn with it.
 */
inline constexpr uint16_t kPongPalette[16] = {
    0x0863,  //  0  #0A0C18  court ink - night playfield and band. Color::Black; never 0x0000
    0xF7DF,  //  1  #F4F8FF  arcade white - ball specular, paddle edge, scores, overlay text
    0x10E7,  //  2  #141C3A  court navy - the playfield fill; also the P1 paddle cap. Color::Navy
    0x1A75,  //  3  #1D4FA8  P1 blue - player one's paddle inner band. Color::Blue
    0x371D,  //  4  #35E0E8  P1 cyan tube - player one's paddle body and HUD tag. Color::Cyan
    0x0B6B,  //  5  #0B6E5A  deep teal - spare cool shade for the left half of the court
    0x2DEE,  //  6  #2FBF71  arcade green - dim tick ink for the net diagnostics footer
    0x8F96,  //  7  #8CF0B0  pale mint - bright flash for the same footer
    0xFE49,  //  8  #FFC94D  ball gold - the ball body. Color::Yellow
    0xF3E3,  //  9  #F07C1E  ball ember - the ball's rim, the particle fade target. Color::Orange
    0xFB4F,  // 10  #FF6B7A  P2 rose - player two's paddle body and HUD tag. Color::LightRed
    0xD127,  // 11  #D6263F  P2 red - player two's paddle inner band. Color::Red
    0x68A4,  // 12  #6A1424  P2 maroon - player two's paddle cap. Color::DarkRed
    0x8ADD,  // 13  #8C5BE8  violet - spare cool ink, the net diagnostics accent
    0xF2DB,  // 14  #F05BD8  magenta - spare hot ink, the loudest slot in the table
    0x7C57,  // 15  #7C89B8  slate - court frame, dashed centre line, dim text. Color::Gray
};

static_assert(kPongPalette[0] != 0,
              "PongPalette: slot 0 is Color::Black; 0x0000 would erase every "
              "Color::Black primitive on ESP32");

